import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
total = sum(a)
if total % k:
    print('false')
    raise SystemExit
t = total // k
good = []
for mask in range(1, 1 << n):
    s = 0
    for i in range(n):
        if mask >> i & 1:
            s += a[i]
    if s == t:
        good.append(mask)
full = (1 << n) - 1
seen = set()

def solve(used, groups):
    if used == full:
        return groups == k
    if groups >= k or used in seen:
        return False
    low = 0
    while used >> low & 1:
        low += 1
    for m in good:
        if m >> low & 1 and not (m & used):
            if solve(used | m, groups + 1):
                return True
    seen.add(used)
    return False

print('true' if solve(0, 0) else 'false')

