def gen(rng):
    def fmt(a, k):
        return f"{len(a)} {k}\n" + ' '.join(map(str, a))
    def split(total, m):
        cuts = sorted(rng.sample(range(1, total), m - 1)) if m > 1 else []
        pts = [0] + cuts + [total]
        return [pts[i + 1] - pts[i] for i in range(m)]
    def build(n, k, T):
        sizes = [1] * k
        for _ in range(n - k):
            sizes[rng.randrange(k)] += 1
        a = []
        for m in sizes:
            a += split(T, m)
        rng.shuffle(a)
        return a
    def perturb(a):
        b = a[:]
        if len(b) < 2:
            return b
        for _ in range(50):
            i, j = rng.sample(range(len(b)), 2)
            d = rng.randint(1, 3)
            if b[i] > d:
                b[i] -= d
                b[j] += d
                if max(b) <= 10 ** 4:
                    return b
        return b
    tests = [fmt([5], 1), fmt([7, 7], 1), fmt([1, 1], 2), fmt([1, 2], 2), fmt([2, 2, 2, 2], 4), fmt([10 ** 4] * 16, 16), fmt([10 ** 4] * 16, 4), fmt([10 ** 4] * 15 + [9999], 4), fmt([1] * 16, 5), fmt([1] * 16, 8)]
    for _ in range(40):
