            a = [rng.randint(1, 9) for _ in range(n)]
        else:
            T = rng.randint(3, 30)
            if T < max(1, n // k + 1):
                T = n
            a = build(n, k, max(T, n - k + 1))
            if mode < 0.65:
                a = perturb(a)
        tests.append(fmt(a, k))
